import{_t as e,it as t,n,rt as r}from"./chunks/framework.DmGhRbf7.js";import{an as i,in as a,on as o,rn as s}from"./chunks/assets.wGwX1-II.js";var c=JSON.parse(`{"title":"Navigation Block","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-plugin/user/navigation-block.md","filePath":"content/plugins/bcew-plugin/user/navigation-block.md"}`),l={name:`content/plugins/bcew-plugin/user/navigation-block.md`};function u(n,c,l,u,d,f){return e(),r(`div`,null,[...c[0]||=[t(`<h1 id="navigation-block" tabindex="-1">Navigation Block <a class="header-anchor" href="#navigation-block" aria-label="Permalink to “Navigation Block”">​</a></h1><p>Add a site navigation menu to pages and posts. This block extends the WordPress core Navigation block with improved styling, submenu handling, and a mobile overlay menu.</p><p>Find it in:</p><ul><li>Block Inserter (+) → Design System → Navigation</li></ul><p>After inserting the block, select a WordPress Menu in the block settings.</p><p><img src="`+o+`" alt="Add the Navigation Block" width="640" height="410"></p><h2 id="navigation-block-behavior" tabindex="-1">Navigation Block behavior <a class="header-anchor" href="#navigation-block-behavior" aria-label="Permalink to “Navigation Block behavior”">​</a></h2><ul><li>Uses your existing WordPress Menus: <ul><li>Create or edit menus in WordPress Admin → Appearance → Menus.</li><li>In the block settings, choose which Menu to display.</li></ul></li><li>Enhanced styling for top-level items, nested submenus, editor preview, and mobile menu toggle.</li><li>Responsive behavior: <ul><li>Desktop: inline menu.</li><li>Mobile: optional full-screen overlay with a toggle.</li><li>Overlay behavior is controlled by Overlay Mode and the Mobile Breakpoint.</li></ul></li></ul><p><img src="`+i+`" alt="Mobile navigation overlay" width="392" height="746"></p><h2 id="key-settings" tabindex="-1">Key settings <a class="header-anchor" href="#key-settings" aria-label="Permalink to “Key settings”">​</a></h2><ul><li>Overlay Mode: <ul><li>Always Overlay: Always show as an overlay with a toggle.</li><li>Mobile Overlay: Switch to overlay below the Mobile Breakpoint.</li><li>Never Overlay: Always show as a standard inline menu.</li></ul></li><li>Mobile Breakpoint: <ul><li>Width at which Mobile Overlay activates (for Mobile Overlay mode).</li><li>Default: 768px.</li><li>Adjustable in the block settings.</li></ul></li><li>Visibility: <ul><li>Show on Desktop: Visible at widths ≥ Mobile Breakpoint.</li><li>Show on Mobile: Visible at widths &lt; Mobile Breakpoint.</li><li>If both are disabled, the menu still renders as a safety fallback to avoid hiding site navigation entirely.</li></ul></li></ul><p><img src="`+a+`" alt="Navigation Block Settings" width="278" height="346"></p><h2 id="submenus" tabindex="-1">Submenus <a class="header-anchor" href="#submenus" aria-label="Permalink to “Submenus”">​</a></h2><ul><li>Desktop: Open on hover; close when the pointer leaves the submenu area.</li><li>Mobile: Open/close via the arrow toggle next to the parent item.</li><li>Nested submenus are positioned to remain within the viewport.</li><li>Behavior mirrors the core Navigation block for keyboard and screen-reader support.</li></ul><h2 id="usage-tips" tabindex="-1">Usage tips <a class="header-anchor" href="#usage-tips" aria-label="Permalink to “Usage tips”">​</a></h2><ul><li>Keep mobile labels concise to prevent wrapping in the overlay.</li><li>Manage structure in Appearance → Menus; items are not added in the block editor.</li><li>Test across breakpoints to confirm overlay and visibility match expectations.</li></ul><h2 id="navigation-block-testing" tabindex="-1">Navigation Block testing <a class="header-anchor" href="#navigation-block-testing" aria-label="Permalink to “Navigation Block testing”">​</a></h2><ol><li>Add the Navigation block to a page or post.</li><li>In the settings panel, select a WordPress Menu.</li><li>Configure Overlay Mode, Mobile Breakpoint, and Visibility.</li><li>View the page and resize: <ul><li>Above the breakpoint: confirm desktop menu and hover submenus.</li><li>Below the breakpoint: confirm mobile toggle, overlay, and tap-to-open submenus.</li></ul></li><li>Confirm the current page is highlighted in the menu.</li></ol><p><img src="`+s+`" alt="Navigation Block HOWTO" width="640" height="410"></p><h2 id="navigation-block-troubleshooting" tabindex="-1">Navigation Block troubleshooting <a class="header-anchor" href="#navigation-block-troubleshooting" aria-label="Permalink to “Navigation Block troubleshooting”">​</a></h2><ul><li>No menu appears: <ul><li>Ensure a Menu is selected in the block settings.</li><li>Verify the selected Menu has items in Appearance → Menus.</li></ul></li><li>Overlay toggle not visible on mobile: <ul><li>Set Overlay Mode to Mobile Overlay or Always Overlay.</li><li>Ensure Show on Mobile is enabled and the breakpoint is appropriate.</li></ul></li><li>Can’t hide the menu entirely: both visibility toggles off still render the block as a safety fallback.</li></ul>`,21)]])}var d=n(l,[[`render`,u]]);export{c as __pageData,d as default};